<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class PurchaseOrderLine extends Model {protected $fillable=['purchase_order_id','inventory_product_id','quantity','received_quantity','unit_price','discount','line_total']; protected $casts=['unit_price'=>'decimal:2','discount'=>'decimal:2','line_total'=>'decimal:2']; public function order():BelongsTo{return $this->belongsTo(PurchaseOrder::class,'purchase_order_id');} public function product():BelongsTo{return $this->belongsTo(InventoryProduct::class,'inventory_product_id');}}